I must be doing something stupid.  Here's my little test program:
<code>
#!/usr/bin/perl

use v5.10 ;
use strict;
use warnings ;

my $BOM  = "\xef\xbb\xbf" ;

die "no args\n" unless @ARGV == 2 ;
open (my $i, "<", $ARGV[0]) or die "Can't open $ARGV[0]\n" ;
open (my $o, ">", $ARGV[1]) or die "Can't write to $ARGV[1]\n" ;
say "marker is" ;
printhex ($BOM) ;
say "" ;
while (my $line = <$i>)
{   my $newline = $line ;
    printhex ($newline) ;
    $newline =~ s/$BOM//g; 
    die "didn't change" if $newline eq $line ;
    print $o $newline ; 
}
close $i ;
close $o ;
exit ;

sub printhex
{   my $str = $_[0] ;
    for my $chr (split(//,$str))
    {   printf("%x ", ord($chr)) ; }
}
</code>
